WT_DECLARE_WT_MEMBER(1,JavaScriptConstructor,"WDateTimeValidator",(function(e,t,i,a,g,s,n,l){this.validate=function(r){if(0===r.length)return e?{valid:!1,message:g}:{valid:!0};let o,d=-1,u=-1,c=-1,m=-1,f=-1,v=-1,M=-1;for(const e of t){o=new RegExp("^"+e.regexp+"$").exec(r);if(null!==o){d=e.getMonth(o);u=e.getDay(o);c=e.getYear(o);m=e.getHour(o);r.toUpperCase().indexOf("P")>-1&&m<12?m+=12:r.toUpperCase().indexOf("A")>-1&&12===m&&(m=0);f=e.getMinutes(o);v=e.getSeconds(o);M=e.getMilliseconds(o);break}}if(null===o)return{valid:!1,message:s};if(u<=0||u>31||d<=0||d>12||m<0||m>23||f<0||f>59||v<0||v>59||M<0||M>999)return{valid:!1,message:s};const p=new Date(c,d-1,u,m,f,v,M);return p.getDate()!==u||p.getMonth()!==d-1||p.getFullYear()!==c||p.getFullYear()<1400||p.getHours()!==m||p.getMinutes()!==f||p.getSeconds()!==v||p.getMilliseconds()!==M?{valid:!1,message:s}:i&&p.getTime()<i.getTime()?{valid:!1,message:n}:a&&p.getTime()>a.getTime()?{valid:!1,message:l}:{valid:!0}}}));